CREATE OR REPLACE FUNCTION private.guard_wmp_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  uid uuid := auth.uid();
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if uid is null then
    raise exception using errcode='28000', message='AUTH_REQUIRED';
  end if;

  -- worker_account_id must always match the caller
  if new.worker_account_id is distinct from uid then
    raise exception using errcode='42501',
      message='WMP_ACCOUNT_MUST_BE_CALLER';
  end if;

  -- On UPDATE, worker_account_id is immutable
  if tg_op = 'UPDATE' and new.worker_account_id is distinct from old.worker_account_id then
    raise exception using errcode='42501',
      message='WMP_ACCOUNT_IMMUTABLE';
  end if;

  -- worker_profile_id must be owned by the caller and be a WORKER profile
  if not exists (
    select 1 from public.app_profiles p
     where p.id = new.worker_profile_id
       and p.account_id = uid
       and p.kind = 'WORKER'
  ) then
    raise exception using errcode='42501',
      message='WMP_PROFILE_NOT_OWNED_BY_CALLER';
  end if;

  -- On UPDATE, worker_profile_id is immutable (PK-like semantics)
  if tg_op = 'UPDATE' and new.worker_profile_id is distinct from old.worker_profile_id then
    raise exception using errcode='42501',
      message='WMP_PROFILE_IMMUTABLE';
  end if;

  return new;
end;
$function$

body:
declare
  uid uuid := auth.uid();
begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  if uid is null then
    raise exception using errcode='28000', message='AUTH_REQUIRED';
  end if;

  -- worker_account_id must always match the caller
  if new.worker_account_id is distinct from uid then
    raise exception using errcode='42501',
      message='WMP_ACCOUNT_MUST_BE_CALLER';
  end if;

  -- On UPDATE, worker_account_id is immutable
  if tg_op = 'UPDATE' and new.worker_account_id is distinct from old.worker_account_id then
    raise exception using errcode='42501',
      message='WMP_ACCOUNT_IMMUTABLE';
  end if;

  -- worker_profile_id must be owned by the caller and be a WORKER profile
  if not exists (
    select 1 from public.app_profiles p
     where p.id = new.worker_profile_id
       and p.account_id = uid
       and p.kind = 'WORKER'
  ) then
    raise exception using errcode='42501',
      message='WMP_PROFILE_NOT_OWNED_BY_CALLER';
  end if;

  -- On UPDATE, worker_profile_id is immutable (PK-like semantics)
  if tg_op = 'UPDATE' and new.worker_profile_id is distinct from old.worker_profile_id then
    raise exception using errcode='42501',
      message='WMP_PROFILE_IMMUTABLE';
  end if;

  return new;
end;

with material as (
  select jsonb_build_object('profileId',p.id,'accountId',p.account_id,'operatingCountryCode',p.operating_country_code,'city',p.city,'radiusKm',p.radius_km,
    'approximatePosition',case when w.approximate_lat is not null and w.approximate_lng is not null then
      jsonb_build_object('latitude',w.approximate_lat,'longitude',w.approximate_lng) else null end) as doc
  from public.app_profiles p left join public.worker_match_preferences w on w.worker_profile_id=p.id where p.id=pid and p.kind='WORKER'
) select doc||jsonb_build_object('revision',encode(extensions.digest(doc::text,'sha256'),'hex')) from material;

